    desc: "Сравнительное исследование таргетной фототермической терапии меланомы с использованием плазмонных золотых наностержней, модифицированных двумя типами пептидов-агонистов рецептора MC1R (Ac-12 и GKR) для улучшения доставки в опухоль. Авторы теоретически и экспериментально сравнили нагревательные способности этих наночастиц при облучении фемтосекундными и наносекундными лазерными импульсами, выявив, что фемтосекундный режим обеспечивает более интенсивное выделение тепла за счет особенностей релаксации электронной и фононной температур. В экспериментах in vivo на мышиной модели меланомы доказано, что сочетание наностержней с пептидом Ac-12 и фемтосекундного режима дает самое выраженное торможение роста опухоли, до 94 процентов.",
